IF md5(pg_get_functiondef('admin_pass_rewards_read()'::regprocedure))<>'3d1e46cc37f4e410870919d67570b018' OR (SELECT proacl::text FROM pg_proc WHERE oid='admin_pass_rewards_read()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION 'SUPPLY_ROTATION_SOURCE_OR_ACL_DRIFT';END IF;
