END $guard$;
DO $absent$ BEGIN IF to_regclass('private.supply_rotation_config') IS NOT NULL OR to_regclass('private.oak_completion_gifts') IS NOT NULL THEN RAISE EXCEPTION 'SUPPLY_ROTATION_ALREADY_INSTALLED';END IF;END;$absent$;
CREATE TABLE private.supply_rotation_config(id boolean PRIMARY KEY DEFAULT true CHECK(id), plan jsonb NOT NULL, active_from timestamptz NOT NULL, oak_starts date NOT NULL, enabled boolean NOT NULL DEFAULT true, oak_enabled boolean NOT NULL DEFAULT true);
ALTER TABLE private.supply_rotation_config ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.supply_rotation_config FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE private.oak_completion_gifts(user_id uuid NOT NULL REFERENCES public.profiles(id), completed_on date NOT NULL, candy_quantity integer NOT NULL CHECK(candy_quantity=10), items jsonb NOT NULL, claimed_family integer, request_id uuid, result jsonb, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), claimed_at timestamptz, PRIMARY KEY(user_id,completed_on),UNIQUE(user_id,request_id));
CREATE INDEX oak_completion_pending ON private.oak_completion_gifts(user_id,completed_on) WHERE claimed_at IS NULL;
ALTER TABLE private.oak_completion_gifts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.oak_completion_gifts FROM PUBLIC,anon,authenticated,service_role;

